  // a[i] = i*i - i + 1 for i=1..n
  // We want triples i<j<k with (a[i]+a[j]+a[k]) % 3 == 0

  // Compute residues mod 3 of a[i]
  // a[i] mod 3 = (i*i - i + 1) mod 3
  // Let's analyze the pattern of a[i] mod 3 for i=1..n

  // Count how many a[i] are congruent to 0,1,2 mod 3
  let count = [0, 0, 0];
  for (let i = 1; i <= n; i++) {
    let val = (i * i - i + 1) % 3;
    if (val < 0) val += 3;
    count[val]++;
  }

  // We want number of triples (i<j<k) with residues r1,r2,r3 such that (r1+r2+r3)%3==0
  // Possible residue triples (r1,r2,r3) with sum mod 3 == 0:
  // (0,0,0), (1,1,1), (2,2,2), (0,1,2)

  // Number of triples from count[r]:
  // C(count[r],3) for (r,r,r)
  // For (0,1,2), number of triples is count[0]*count[1]*count[2]

  function comb3(x) {
    if (x < 3) return 0;
    return (x * (x - 1) * (x - 2)) / 6;
  }

  const res =
    comb3(count[0]) +
    comb3(count[1]) +
    comb3(count[2]) +
    count[0] * count[1] * count[2];

  return res;
}

