    { grade: "A", min: 3.7 },
    { grade: "A-", min: 3.3 },
    { grade: "B+", min: 3.0 },
    { grade: "B", min: 2.7 },
    { grade: "B-", min: 2.3 },
    { grade: "C+", min: 2.0 },
    { grade: "C", min: 1.7 },
    { grade: "C-", min: 1.3 },
    { grade: "D+", min: 1.0 },
    { grade: "D", min: 0.7 },
    { grade: "D-", min: 0.0 }
  ];
  return gpas.map(gpa => {
    if (gpa === 4) return "A+";
    if (gpa === 0) return "E";
