function solve([rows, x]) {
  const out = [];
  for (let i = 0; i < rows.length; i++) {
    const r = rows[i];
    const cols = [];
    for (let j = 0; j < r.length; j++) {
      if (r[j] === x) cols.push(j);
    }
    cols.sort((a, b) => b - a);
    for (const j of cols) out.push([i, j]);
  }
  return out;
}

